use cyberguard_sca::models::Ecosystem;
use cyberguard_sca::parsers::CargoLockParser;
use cyberguard_sca::traits::LockfileParser;
use std::path::Path;

#[test]
fn test_cargo_lock_parser_valid_toml() {
    let toml_content = r#"
# This file is automatically @generated by Cargo.
version = 3

[[package]]
name = "aho-corasick"
version = "1.1.3"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "8e60d3430d3a69478ad0993f19238d2df97c507009a52b3c10addcd7f6bcb916"
dependencies = [
 "memchr",
]

[[package]]
name = "memchr"
version = "2.7.4"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "78ca9ab1a0babb1e7d5695e3530886289c18cf2f87ec19a575a0abdce112e3a3"

[[package]]
name = "root-app"
version = "0.1.0"
dependencies = [
 "aho-corasick",
]
"#;

    let parser = CargoLockParser::new();
    assert!(parser.can_parse(Path::new("Cargo.lock")));
    assert!(parser.can_parse(Path::new("/path/to/my/Cargo.lock")));
    assert!(!parser.can_parse(Path::new("package-lock.json")));

    let packages = parser.parse(Path::new("Cargo.lock"), toml_content).unwrap();

    assert_eq!(packages.len(), 3);

    let aho = packages.iter().find(|p| p.name == "aho-corasick").unwrap();
    assert_eq!(aho.version, "1.1.3");
    assert_eq!(aho.ecosystem, Ecosystem::Cargo);
    assert_eq!(aho.purl, "pkg:cargo/aho-corasick@1.1.3");
    assert_eq!(
        aho.checksum.as_deref(),
        Some("8e60d3430d3a69478ad0993f19238d2df97c507009a52b3c10addcd7f6bcb916")
    );
    assert_eq!(aho.dependencies, vec!["memchr".to_string()]);

    let memchr = packages.iter().find(|p| p.name == "memchr").unwrap();
    assert_eq!(memchr.version, "2.7.4");
}

#[test]
fn test_cargo_lock_parser_invalid_syntax() {
    let invalid_content = r#"
[[package
name = incomplete
"#;

    let parser = CargoLockParser::new();
    let result = parser.parse(Path::new("Cargo.lock"), invalid_content);
    assert!(result.is_err());
}
